mapper.select:
SELECT shard_id,step_key,step_id,state,round,attempts,error_type FROM catalog_step WHERE shard_id=#{shard}
  AND source_id=#{key.source} AND command_scope=#{key.scope} AND command_id=#{key.command} AND step_key>#{after}
  ORDER BY step_key LIMIT #{limit}

SELECT shard_id,outbox_id,aggregate_version,state,round,attempts,broker_partition,broker_offset,error_type FROM catalog_outbox
WHERE shard_id=#{shard} AND source_id=#{key.source} AND command_scope=#{key.scope} AND command_id=#{key.command}
  AND purpose='KAFKA' AND outbox_id>#{after} ORDER BY outbox_id LIMIT #{limit}
